// Сложный уровень: варианты ответов сбалансированы по длине, ловушки на типовые перепутывания.
// Форматы: прямые вопросы, "что НЕВЕРНО", "какие утверждения верны" (короткие варианты вида "1 и 3"),
// узнавание формул среди похожих. Задачи — в два действия.

const THEORY_HARD = [
// ===== Комбинированные утверждения (короткие варианты) =====
{topic:"Работа и энергия",q:"Какие утверждения о консервативных силах верны? 1) работа не зависит от пути; 2) работа на замкнутом пути равна нулю; 3) такие силы всегда тормозят тело.",options:["Только 1 и 2","Только 1 и 3","Только 2 и 3","Все три"],answer:0,hint:"Пункт 3 описывает совсем другой тип сил — вспомни, какие силы всегда против скорости.",why:"Верны 1 и 2 — это два эквивалентных определения консервативных сил. Пункт 3 описывает диссипативные силы (трение)."},
{topic:"Динамика",q:"Что верно для инерциальной системы отсчёта? 1) тело без воздействий движется равномерно; 2) выполняются законы Ньютона; 3) возникают силы инерции.",options:["Только 1 и 2","Только 1 и 3","Только 2 и 3","Все три"],answer:0,hint:"Силы инерции — признак как раз «неправильной» системы отсчёта.",why:"Верны 1 и 2. Силы инерции F_in = −ma возникают в НЕинерциальных системах отсчёта."},
{topic:"Работа и энергия",q:"Что верно о потенциальной энергии? 1) определена с точностью до произвольной константы; 2) может быть отрицательной; 3) всегда равна mgh.",options:["Только 1 и 2","Только 1 и 3","Только 2 и 3","Все три"],answer:0,hint:"mgh — лишь частный случай для однородного поля тяжести.",why:"Верны 1 и 2: начало отсчёта произвольно, значит U может быть отрицательной. U = mgh — только для поля тяжести; для пружины U = kx²/2."},
{topic:"Волны",q:"Что верно для упругой волны? 1) переносит энергию; 2) переносит вещество; 3) частицы среды колеблются около положений равновесия.",options:["Только 1 и 3","Только 1","Только 2 и 3","Все три"],answer:0,hint:"Если бы волна переносила вещество, за звуковой волной летел бы воздух.",why:"Верны 1 и 3: волна переносит энергию (вектор Умова), но вещество не переносится — частицы лишь колеблются около равновесия."},
{topic:"Волны",q:"В каких средах распространяются поперечные волны? 1) твёрдые; 2) жидкости; 3) газы.",options:["Только 1","Только 1 и 2","Во всех трёх","Только 2 и 3"],answer:0,hint:"Нужна реакция среды на сдвиг — какая среда ей сопротивляется?",why:"Только твёрдые тела сопротивляются сдвигу — поперечные волны возможны лишь там. В жидкостях и газах — только продольные."},
{topic:"МКТ",q:"Что верно о квазистатическом процессе? 1) это последовательность равновесных состояний; 2) он обратим; 3) он протекает быстро.",options:["Только 1 и 2","Только 1 и 3","Только 2 и 3","Все три"],answer:0,hint:"«Квазиравновесный» означает бесконечно медленный.",why:"Верны 1 и 2: квазистатический процесс бесконечно медленный, идёт через равновесные состояния и потому обратим. Быстрые процессы — неравновесные."},
{topic:"МКТ",q:"Что верно об идеальном газе? 1) молекулы — материальные точки; 2) нет межмолекулярных сил; 3) есть потенциальная энергия взаимодействия молекул.",options:["Только 1 и 2","Только 1 и 3","Только 2 и 3","Все три"],answer:0,hint:"Пункт 3 противоречит пункту 2 — одно из них лишнее.",why:"Верны 1 и 2. У идеального газа нет сил между молекулами → нет и потенциальной энергии взаимодействия; U — только кинетическая. Это отличие от реального газа."},
{topic:"Термодинамика",q:"Что верно о цикле Карно? 1) две изотермы; 2) две адиабаты; 3) максимальный КПД при данных T₁ и T₂.",options:["Все три","Только 1 и 2","Только 1 и 3","Только 3"],answer:0,hint:"Цикл обратим и без теплообмена при конечной ΔT — отсюда максимум.",why:"Всё верно: цикл Карно = две изотермы + две адиабаты; он квазиравновесен, обратим, и η_Карно = η_max."},
{topic:"Статфизика",q:"Что верно об энтропии изолированной системы? 1) не может убывать; 2) в равновесии максимальна; 3) всегда возрастает.",options:["Только 1 и 2","Только 1 и 3","Только 2 и 3","Все три"],answer:0,hint:"А если процесс обратимый?",why:"Верны 1 и 2: dS ≥ 0, но при обратимом процессе S = const — «всегда возрастает» неверно. Максимум — в равновесии."},
{topic:"Динамика",q:"Что верно о силах трения? 1) электромагнитной природы; 2) фундаментальные силы; 3) диссипативные.",options:["Только 1 и 3","Только 1 и 2","Только 2 и 3","Все три"],answer:0,hint:"Фундаментальных взаимодействий всего четыре — трения среди них нет.",why:"Верны 1 и 3: трение — электромагнитная по природе (межмолекулярное), но НЕ фундаментальная сила; направлено против скорости → диссипативно."},
{topic:"Волны",q:"Что верно о стоячей волне? 1) образуется двумя встречными когерентными волнами одинаковой амплитуды; 2) энергия вдоль оси не переносится; 3) амплитуда во всех точках одинакова.",options:["Только 1 и 2","Только 1 и 3","Только 2 и 3","Все три"],answer:0,hint:"Амплитуда меняется от точки к точке — вспомни про узлы.",why:"Верны 1 и 2: два встречных потока энергии компенсируются; амплитуда ξ = 2a·cos(kx) зависит от x — в узлах равна нулю."},
{topic:"Работа и энергия",q:"При абсолютно упругом ударе: 1) сохраняется импульс; 2) сохраняется кинетическая энергия; 3) тела движутся вместе после удара.",options:["Только 1 и 2","Только 1 и 3","Только 2 и 3","Все три"],answer:0,hint:"Движутся вместе — это про другой вид удара.",why:"Верны 1 и 2. Совместное движение после удара — признак абсолютно НЕупругого удара; при упругом тела разлетаются."},
{topic:"Работа и энергия",q:"При абсолютно неупругом ударе: 1) сохраняется импульс; 2) сохраняется кинетическая энергия; 3) часть энергии переходит во внутреннюю.",options:["Только 1 и 3","Только 1 и 2","Только 2 и 3","Все три"],answer:0,hint:"Тела при этом нагреваются.",why:"Верны 1 и 3: импульс сохраняется всегда (замкнутая система), а кинетическая энергия частично переходит во внутреннюю — тела деформируются и греются."},
{topic:"Вращение",q:"Что верно о свободной оси гироскопа? 1) сохраняет направление в пространстве; 2) под моментом сил прецессирует; 3) момент импульса всегда нулевой.",options:["Только 1 и 2","Только 1 и 3","Только 2 и 3","Все три"],answer:0,hint:"Гироскоп — это как раз тело с большим L = Iω.",why:"Верны 1 и 2: без моментов сил ось сохраняет направление (L = const); с моментом — прецессирует. Момент импульса у гироскопа большой, а не нулевой."},
{topic:"Колебания",q:"Что верно об установившихся вынужденных колебаниях? 1) частота равна частоте вынуждающей силы; 2) амплитуда зависит от частоты силы; 3) идут с собственной частотой ω₀.",options:["Только 1 и 2","Только 1 и 3","Только 2 и 3","Все три"],answer:0,hint:"Собственная частота нужна лишь для формулы амплитуды.",why:"Верны 1 и 2: установившиеся колебания идут с частотой силы ω, амплитуда зависит от ω через знаменатель (ω₀²−ω²)²+4β²ω²."},
{topic:"Колебания",q:"Что верно о затухающих колебаниях? 1) амплитуда убывает как e^(−βt); 2) период больше периода собственных колебаний; 3) β не зависит от свойств среды.",options:["Только 1 и 2","Только 1 и 3","Только 2 и 3","Все три"],answer:0,hint:"β = r/2m — а r это что?",why:"Верны 1 и 2: a = a₀e^(−βt), T = 2π/√(ω₀²−β²) > T₀. Коэффициент β = r/2m зависит от сопротивления среды r."},
{topic:"Реальные газы",q:"Что верно о жидкостях? 1) есть только ближний порядок; 2) структура квазикристаллическая; 3) есть дальний порядок как у кристаллов.",options:["Только 1 и 2","Только 1 и 3","Только 2 и 3","Все три"],answer:0,hint:"Дальний порядок — признак кристалла, у жидкости он размывается.",why:"Верны 1 и 2: в жидкости упорядочены только ближайшие соседи (ближний порядок), структура называется квазикристаллической. Дальнего порядка нет."},

// ===== Похожие формулы — выбери верную =====
{topic:"Кинематика",q:"Нормальное ускорение при движении по криволинейной траектории:",options:["an = v²/R","aτ = dv/dt","ε = dω/dt","v = ωR"],answer:0,hint:"Все четыре формулы верные — вопрос в том, какая именно про нормальное ускорение.",why:"an = v²/R. Остальные: dv/dt — тангенциальное ускорение, dω/dt — угловое ускорение, ωR — линейная скорость."},
{topic:"Вращение",q:"Момент инерции сплошного однородного шара относительно оси через центр:",options:["2mR²/5","mR²/2","mR²","ml²/12"],answer:0,hint:"У шара масса ближе к оси, чем у диска, — коэффициент меньше 1/2.",why:"Шар: 2mR²/5. Диск/цилиндр: mR²/2, обруч: mR², стержень: ml²/12."},
{topic:"Вращение",q:"Момент инерции тонкого обруча (кольца) относительно оси симметрии:",options:["mR²","mR²/2","2mR²/5","mR²/3"],answer:0,hint:"Вся масса обруча находится на одном расстоянии R от оси.",why:"Обруч: I = mR² — вся масса на расстоянии R. У диска mR²/2, у шара 2mR²/5."},
{topic:"Вращение",q:"Момент инерции тонкого стержня относительно оси, перпендикулярной стержню и проходящей через его середину:",options:["ml²/12","ml²/3","mR²/2","ml²/2"],answer:0,hint:"Через конец стержня было бы ml²/3 — а по Штейнеру ml²/12 + m(l/2)² = ml²/3.",why:"Через середину: ml²/12; через конец: ml²/3 (следует из теоремы Штейнера: ml²/12 + m(l/2)² = ml²/3)."},
{topic:"МКТ",q:"Средняя кинетическая энергия поступательного движения молекулы:",options:["(3/2)kT","(1/2)kT","kT","(5/2)kT"],answer:0,hint:"На степень свободы приходится kT/2. Сколько поступательных степеней?",why:"(3/2)kT: поступательных степеней 3, на каждую kT/2. (5/2)kT — полная энергия двухатомной молекулы без колебаний."},
{topic:"МКТ",q:"Молярная теплоёмкость при постоянном объёме одноатомного идеального газа:",options:["(3/2)R","(5/2)R","R","(7/2)R"],answer:0,hint:"C_V = (i/2)R, для одноатомного газа i = 3.",why:"C_V = (3/2)R для одноатомного (i=3). (5/2)R — двухатомный без колебаний, (7/2)R — двухатомный с колебаниями."},
{topic:"МКТ",q:"Показатель адиабаты γ для одноатомного идеального газа:",options:["5/3","7/5","4/3","3/2"],answer:0,hint:"γ = (i+2)/i, i = 3.",why:"γ = (3+2)/3 = 5/3. Для двухатомного без колебаний i=5 → γ=7/5."},
{topic:"Термодинамика",q:"КПД цикла Карно:",options:["1 − T₂/T₁","T₁/T₂","(T₁ − T₂)/T₂","T₂/T₁"],answer:0,hint:"Все варианты похожи — проверь, что при T₂→T₁ КПД должен стремиться к нулю.",why:"η = (T₁−T₂)/T₁ = 1 − T₂/T₁. Вариант (T₁−T₂)/T₂ — ловушка: в знаменателе T₁, а не T₂ (иначе η мог бы превышать 1)."},
{topic:"Термодинамика",q:"Холодильный коэффициент обращённого цикла Карно:",options:["T₂/(T₁ − T₂)","T₁/(T₁ − T₂)","(T₁ − T₂)/T₂","1 − T₂/T₁"],answer:0,hint:"В числителе — та температура, откуда забираем тепло (холодильник).",why:"β_х = Q₂/A = T₂/(T₁−T₂). Вариант T₁/(T₁−T₂) — коэффициент теплового насоса β_T (отдаём тепло нагревателю)."},
{topic:"Колебания",q:"Резонансная частота вынужденных колебаний:",options:["√(ω₀² − 2β²)","√(ω₀² − β²)","ω₀","√(ω₀² + 2β²)"],answer:0,hint:"Частота затухающих колебаний — √(ω₀²−β²), а резонансная — другая.",why:"ω_рез = √(ω₀²−2β²) — минимум знаменателя (ω₀²−ω²)²+4β²ω². Частота затухающих колебаний √(ω₀²−β²) — частая путаница."},
{topic:"Колебания",q:"Период физического маятника:",options:["2π√(I/mgl)","2π√(mgl/I)","2π√(l/g)","2π√(I/mg)"],answer:0,hint:"У математического 2π√(l/g); приведённая длина l_пр = I/(ml).",why:"T = 2π√(I/mgl). Вариант 2π√(l/g) — математический маятник."},
{topic:"Волны",q:"Волновое число k:",options:["2π/λ","π/λ","λ/2π","2πλ"],answer:0,hint:"Аналог ω = 2π/T, только по пространству.",why:"k = 2π/λ — по аналогии с ω = 2π/T (ω — по времени, k — по координате)."},
{topic:"МКТ",q:"Давление идеального газа по уравнению Клаузиуса:",options:["(2/3)n⟨ε_пост⟩","(1/2)n⟨ε_пост⟩","(3/2)n⟨ε_пост⟩","n⟨ε_пост⟩"],answer:0,hint:"Помни, что ⟨ε_пост⟩ = (3/2)kT — подставь и проверь размерность.",why:"p = (2/3)n⟨ε_пост⟩ = (1/3)nm⟨v²⟩. Подстановка ⟨ε⟩ = (3/2)kT даёт p = nkT — проверка согласованности."},
{topic:"Статфизика",q:"Средняя скорость молекул газа:",options:["√(8kT/πm)","√(3kT/m)","√(2kT/m)","√(kT/m)"],answer:0,hint:"Не перепутай со среднеквадратичной — там тройка.",why:"⟨v⟩ = √(8kT/πm). Среднеквадратичная √(3kT/m) — чуть больше, т.к. квадрат сильнее взвешивает быстрые молекулы."},
{topic:"Термодинамика",q:"Барометрическая формула для изотермической атмосферы:",options:["p = p₀e^(−Mgh/RT)","p = p₀e^(−mgh/RT)","p = p₀e^(Mgh/RT)","p = p₀(1 − gh/RT)"],answer:0,hint:"В показателе — молярная масса M и газовая постоянная R (или m и k).",why:"p = p₀e^(−Mgh/RT): M с R идут парой (как m с k). Знак минус — давление падает с высотой."},
{topic:"Термодинамика",q:"Работа одного моля идеального газа при изотермическом расширении:",options:["RT·ln(V₂/V₁)","p(V₂ − V₁)","C_V·ΔT","RT·(V₂/V₁)"],answer:0,hint:"При T = const давление не постоянно — p(V) под интегралом.",why:"A = ∫p dV = RT∫dV/V = RT·ln(V₂/V₁). p(V₂−V₁) — это изобарный процесс."},
{topic:"Термодинамика",q:"Уравнение адиабатного процесса (Пуассона):",options:["pV^γ = const","pV = const","TV^γ = const","pV^(γ−1) = const"],answer:0,hint:"Адиабата круче изотермы — показатель больше единицы.",why:"pV^γ = const. pV = const — изотерма. Правильные альтернативные формы: TV^(γ−1) = const и T^γ p^(1−γ) = const."},
{topic:"Статфизика",q:"Приращение энтропии в элементарном обратимом процессе:",options:["dS = d′Q/T","dS = T·d′Q","dS = dU/T","dS = Q/T"],answer:0,hint:"d′Q — приведённая теплота; dS — полный дифференциал, d′Q — нет.",why:"dS = d′Q/T — элементарное приращение; интеграл по обратимому процессу ΔS = ∫d′Q/T. Вариант dU/T путает теплоту с энергией."},
{topic:"Волны",q:"Среднее значение вектора Умова (интенсивность волны):",options:["ρa²ω²v/2","ρa²ω²/2","ρa²v/2","ρω²v/2"],answer:0,hint:"⟨w⟩ = ρa²ω²/2, а j = wv — домножь на скорость.",why:"⟨j⟩ = ⟨w⟩v = ρa²ω²v/2. Вариант без v — плотность энергии, а не её поток."},
{topic:"Реальные газы",q:"Сила сопротивления при медленном движении шарика в вязкой среде (Стокс):",options:["F = 6πηrv","F = 6πηr²v","F = ηrv/(6π)","F = 3πηrv"],answer:0,hint:"Проверь размерность: Н = Па·с · м · м/с.",why:"F = 6πηrv — закон Стокса: линейно по r, v и вязкости η."},
{topic:"Реальные газы",q:"Объёмный расход жидкости в трубе (закон Пуазейля):",options:["Q = πR⁴Δp/(8ηl)","Q = πR²Δp/(8ηl)","Q = πR⁴Δp/(4ηl)","Q = R⁴Δp/(8ηl)"],answer:0,hint:"Четвёртая степень радиуса и π в числителе.",why:"Q = πR⁴(p₁−p₂)/(8ηl): зависимость от R⁴ — ключевая (профиль скорости параболический)."},
{topic:"Явления переноса",q:"Коэффициент диффузии в кинетической теории:",options:["D = ⟨v⟩λ/3","D = ⟨v⟩λ","D = 3⟨v⟩λ","D = ⟨v⟩/(3λ)"],answer:0,hint:"Размерность должна быть м²/с — ⟨v⟩·λ. Коэффициент 1/3 — от трёх направлений.",why:"D = (1/3)⟨v⟩λ, аналогично λ_тепл = c_Vρ⟨v⟩λ/3 и η = ρ⟨v⟩λ/3 — единая структура с коэффициентом 1/3."},
{topic:"Динамика",q:"Второй закон Ньютона в импульсной форме:",options:["dp/dt = F","p = F·t","dp = F·v","p/t = F"],answer:0,hint:"F·t — это уже изменение импульса (теорема об импульсе), а не закон.",why:"dp/dt = F — скорость изменения импульса. Интегральная форма Δp = F·Δt — следствие (теорема об импульсе), справедливая при постоянной F."},
{topic:"Динамика",q:"Уравнение движения в неинерциальной системе отсчёта:",options:["mw′ = F + F_in","mw′ = F","mw′ = F_in","mw′ = F − F_in"],answer:0,hint:"Силы инерции добавляются к реальным силам.",why:"mw′ = F + F_in, где F_in = −ma. Чтобы применять уравнения Ньютона в неинерциальной системе, добавляют фиктивные силы инерции."},
{topic:"Колебания",q:"Логарифмический декремент затухания:",options:["λ = βT","λ = β/T","λ = π/β","λ = e^(−βT)"],answer:0,hint:"λ = ln[a(t)/a(t+T)], а a(t) = a₀e^(−βt).",why:"λ = ln[a(t)/a(t+T)] = ln(e^(βT)) = βT. Добротность Q = π/λ."},
{topic:"МКТ",q:"Число степеней свободы i в формуле W = (i/2)kT:",options:["n_пост + n_вр + 2n_кол","n_пост + n_вр + n_кол","2(n_пост + n_вр + n_кол)","n_пост + 2n_вр + n_кол"],answer:0,hint:"У колебательной степени две энергии — кинетическая и потенциальная.",why:"i = n_пост + n_вр + 2n_кол: колебательная степень учитывается дважды, т.к. даёт и кинетическую, и потенциальную энергию по kT/2."},
{topic:"Динамика",q:"Сила вязкого трения при больших скоростях:",options:["F = −k₂v²","F = −k₁v","F = kN","F = const"],answer:0,hint:"Линейный закон — только при малых скоростях.",why:"При больших скоростях линейный закон F = −k₁v переходит в квадратичный F = −k₂v². kN — сухое трение."},
{topic:"Кинематика",q:"Связь тангенциального ускорения с угловым при вращении:",options:["aτ = Rε","aτ = Rω","aτ = Rω²","aτ = ω²R"],answer:0,hint:"Продифференцируй v = ωR по времени.",why:"aτ = dv/dt = R·dω/dt = Rε. Вариант ω²R — нормальное ускорение an, частая путаница."},
{topic:"Волны",q:"Пучности стоячей волны находятся в точках:",options:["x = ±nλ/2","x = ±(2n+1)λ/4","x = ±nλ","x = ±nλ/4"],answer:0,hint:"Пучность — максимум |cos(2πx/λ)|, узел — нуль.",why:"|2a·cos(2πx/λ)| максимальна при 2πx/λ = nπ → x = nλ/2. Узлы — при (2n+1)λ/4."},

// ===== Что НЕВЕРНО =====
{topic:"Динамика",q:"Что из утверждений о весе тела НЕВЕРНО?",options:["Вес всегда равен mg","Вес действует на опору или подвес","В невесомости P = 0","При a↑↑g вес P = m(g−a)"],answer:0,hint:"Вспомни лифт — вес меняется с ускорением.",why:"Неверно, что P = mg всегда: при a↑↓g → P = m(g+a), при a↑↑g → P = m(g−a), при свободном падении P = 0 (невесомость). Остальные утверждения верны."},
{topic:"Работа и энергия",q:"Что НЕВЕРНО о кинетической энергии?",options:["Может быть отрицательной","Равна mv²/2","Зависит от системы отсчёта","Её приращение равно работе всех сил"],answer:0,hint:"v² никогда не бывает отрицательным.",why:"T = mv²/2 ≥ 0 всегда — не может быть отрицательной (в отличие от U). Скорость зависит от системы отсчёта → T тоже. A = T₂−T₁ — теорема верна."},
{topic:"Волны",q:"Что НЕВЕРНО о волновом процессе?",options:["Волна переносит вещество","Волна переносит энергию","Частицы колеблются около равновесия","Существуют продольные и поперечные волны"],answer:0,hint:"Переносится только энергия и фаза колебания.",why:"Волна переносит энергию, но НЕ вещество — частицы колеблются около положений равновесия. Это ключевая особенность волнового движения."},
{topic:"МКТ",q:"Что НЕВЕРНО об идеальном газе?",options:["Между молекулами действуют силы притяжения","Его молекулы считаются материальными точками","Давление создаётся ударами молекул о стенки","Внутренняя энергия зависит только от T"],answer:0,hint:"Силы между молекулами — это про реальный газ (Ван-дер-Ваальс).",why:"У идеального газа нет межмолекулярных сил — потому U содержит только кинетическую энергию и зависит лишь от T. Силы притяжения учитывает уравнение Ван-дер-Ваальса."},
{topic:"Статфизика",q:"Что НЕВЕРНО об энтропии?",options:["В изолированной системе может убывать","Определяется как S = k·lnΩ через статвес","Является функцией состояния системы","В состоянии равновесия принимает максимум"],answer:0,hint:"Закон возрастания энтропии — одно из формулировок второго начала.",why:"Энтропия изолированной системы не может убывать (dS ≥ 0) — это второе начало термодинамики. S = k·lnΩ — функция состояния, максимальна в равновесии."},
{topic:"Термодинамика",q:"Что НЕВЕРНО об адиабатном процессе?",options:["Температура газа не меняется","Теплообмена нет","Работа идёт за счёт внутренней энергии","Адиабата круче изотермы"],answer:0,hint:"d′Q = 0 — но ΔU ≠ 0.",why:"При адиабатном процессе T меняется: расширение → охлаждение, сжатие → нагрев (ΔU = −A). Постоянная T — признак изотермы."},
{topic:"МКТ",q:"Что НЕВЕРНО о теплоте и работе?",options:["Это функции состояния системы","Это способы передачи энергии","Зависят от пути перехода","Q — микроскопический способ"],answer:0,hint:"Функция состояния в конспекте одна — внутренняя энергия (и энтропия).",why:"Q и A — НЕ функции состояния: зависят от пути перехода (поэтому d′, а не d). Функции состояния — U и S."},
{topic:"Динамика",q:"Что НЕВЕРНО о силах инерции?",options:["Они реальны и подчиняются третьему закону Ньютона","Численно равны −ma, где a — ускорение системы","Обусловлены свойствами самой системы отсчёта","Пропорциональны массе тела, подобно тяжести"],answer:0,hint:"Они «фиктивные» — нет тела-источника.",why:"Силы инерции фиктивны: у них нет источника-взаимодействия, третий закон на них не распространяется. Они возникают из-за ускорения системы отсчёта: F_in = −ma."},
{topic:"Колебания",q:"Что НЕВЕРНО о свободных колебаниях?",options:["Их частота зависит от амплитуды","Они изохронны","Идут с собственной частотой","Возникают после вывода из равновесия"],answer:0,hint:"Изохронность — независимость периода от амплитуды — открыта Галилеем.",why:"Свободные (собственные) колебания изохронны: ω₀ = √(k/m) не зависит от амплитуды. Идут с собственной частотой после начального толчка."},
{topic:"Вращение",q:"Что НЕВЕРНО о моменте инерции?",options:["Он не зависит от выбора оси","I = mr² для точки","По Штейнеру I = I_C + ma²","Измеряет инертность при вращении"],answer:0,hint:"Перенеси ось — I изменится.",why:"Момент инерции зависит от оси: по теореме Штейнера I = I_C + ma² минимален для оси через центр масс. Остальное верно."},
{topic:"Статфизика",q:"Что НЕВЕРНО о втором начале термодинамики?",options:["Запрещает любой переход теплоты к нагретому телу","Запрещает существование перпетуум мобиле 2-го рода","Тесно связано с законом возрастания энтропии","Ограничивает КПД тепловой машины: η < 100%"],answer:0,hint:"Холодильник как раз передаёт тепло к горячему телу — но не «единственным результатом».",why:"Второе начало запрещает переход теплоты к горячему телу как ЕДИНСТВЕННЫЙ результат — холодильная машина это делает за счёт работы. Остальное верно."},
{topic:"Реальные газы",q:"Что НЕВЕРНО о критической температуре?",options:["Выше неё газ можно сжижить достаточным давлением","При ней исчезает различие между жидкостью и газом","При ней коэффициент поверхностного натяжения σ → 0","Ниже неё газ принято называть паром"],answer:0,hint:"Смысл критической температуры — предел сжижения.",why:"Выше T_кр газ нельзя превратить в жидкость НИКАКИМ давлением — в этом смысл критической температуры. Остальные утверждения верны."},

// ===== Константы и числа =====
{topic:"МКТ",q:"Постоянная Больцмана k равна:",options:["1,38·10⁻²³ Дж/К","8,31 Дж/(моль·К)","6,02·10²³ моль⁻¹","6,67·10⁻¹¹ СИ"],answer:0,hint:"k = R/N_A.",why:"k = 1,38·10⁻²³ Дж/К. 8,31 — универсальная газовая постоянная R, 6,02·10²³ — число Авогадро, 6,67·10⁻¹¹ — гравитационная постоянная."},
{topic:"МКТ",q:"Универсальная газовая постоянная R равна:",options:["8,31 Дж/(моль·К)","1,38·10⁻²³ Дж/К","6,02·10²³ моль⁻¹","9,8 Дж/К"],answer:0,hint:"R = k·N_A.",why:"R = 8,31 Дж/(моль·К) = k·N_A = 1,38·10⁻²³·6,02·10²³."},
{topic:"МКТ",q:"Число Авогадро равно:",options:["6,02·10²³ моль⁻¹","1,38·10⁻²³","8,31","6,67·10⁻¹¹"],answer:0,hint:"Число атомов в 12 г углерода-12.",why:"N_A = 6,02213·10²³ моль⁻¹ — число частиц в моле."},
{topic:"Динамика",q:"Гравитационная постоянная G равна:",options:["6,67·10⁻¹¹","1,38·10⁻²³","8,31","9,8"],answer:0,hint:"Не путай с g = 9,8 м/с².",why:"G = 6,67·10⁻¹¹ Н·м²/кг² — константа тяготения; g = 9,8 м/с² — ускорение свободного падения у поверхности Земли."},
{topic:"МКТ",q:"Число степеней свободы одноатомной молекулы:",options:["3","5","6","2"],answer:0,hint:"Только поступательное движение — по трём осям.",why:"Одноатомная молекула (материальная точка): i = 3 поступательные. Двухатомная: 3+2=5 без колебаний, 7 с колебаниями."},
{topic:"МКТ",q:"Число степеней свободы двухатомной молекулы без учёта колебаний:",options:["5","3","6","7"],answer:0,hint:"3 поступательные + вращательные. Вокруг оси молекулы вращения нет.",why:"i = 5: 3 поступательные + 2 вращательные (вращение вокруг оси, соединяющей атомы, не считается). С колебаниями — 7."},
{topic:"Реальные газы",q:"Сколько фаз вещества могут одновременно находиться в равновесии?",options:["Не более трёх","Не более двух","Любое число","Только одна"],answer:0,hint:"Тройная точка.",why:"Не более трёх: равновесие трёх фаз возможно только в тройной точке — при единственных значениях T и p."},
{topic:"Динамика",q:"Сколько фундаментальных видов взаимодействий существует?",options:["4","2","3","5"],answer:0,hint:"Гравитация, электромагнетизм и два ядерных.",why:"Четыре: гравитационное, электромагнитное, сильное и слабое. Упругие силы и трение — проявления электромагнитного, не фундаментальны."},
{topic:"МКТ",q:"Объём одного моля идеального газа при нормальных условиях:",options:["22,4 л","2,24 л","224 л","11,2 л"],answer:0,hint:"Из закона Авогадро.",why:"По закону Авогадро моль любого газа при н.у. занимает одинаковый объём — 22,4 л."},

// ===== Перевёрнутые определения и тонкие ловушки =====
{topic:"Кинематика",q:"Какое ускорение изменяет только направление скорости?",options:["Нормальное","Тангенциальное","Полное","Угловое"],answer:0,hint:"Производная модуля скорости — это другой вид ускорения.",why:"Нормальное an = v²/R меняет направление; тангенциальное aτ = dv/dt — модуль. Полное a = aτ + an."},
{topic:"Кинематика",q:"Какое ускорение изменяет только модуль скорости?",options:["Тангенциальное","Нормальное","Центростремительное","Угловое"],answer:0,hint:"aτ = dv/dt — производная именно модуля.",why:"Тангенциальное aτ = dv/dt изменяет модуль скорости; нормальное (центростремительное) — направление."},
{topic:"Динамика",q:"В неинерциальной системе, движущейся с ускорением a, на тело массой m действует сила инерции, направленная:",options:["Противоположно a","По направлению a","Перпендикулярно a","Под углом 45° к a"],answer:0,hint:"F_in = −ma — обрати внимание на знак.",why:"F_in = −ma: в лифте, тормозящем при подъёме, «бросает» в сторону, противоположную ускорению системы."},
{topic:"Динамика",q:"Вес тела в лифте, движущемся с ускорением a, направленным ВНИЗ (a↑↑g):",options:["P = m(g − a)","P = m(g + a)","P = mg","P = 0"],answer:0,hint:"Ускорение сонаправлено с g — вес уменьшается.",why:"При a↑↑g (ускорение вниз) P = m(g−a) — вес меньше; при a = g наступает невесомость. Вариант m(g+a) — при ускорении вверх."},
{topic:"МКТ",q:"Время релаксации — это время, за которое…",options:["Отклонение параметра уменьшается в e раз","Система полностью приходит в состояние равновесия","Температура системы равномерно падает вдвое","Совершается ровно одно полное колебание"],answer:0,hint:"Аналог времени затухания τ = 1/β в колебаниях.",why:"Релаксация — переход к равновесию; время релаксации — время уменьшения отклонения в e раз (характеристика скорости перехода)."},
{topic:"МКТ",q:"Газ при температуре ниже критической называется:",options:["Паром","Идеальным","Ультраразреженным","Насыщенным"],answer:0,hint:"«Насыщенный» — про пар над жидкостью, а не про температуру.",why:"Газ при T < T_кр называется паром — его можно сжижить сжатием. При T > T_кр сжижение невозможно."},
{topic:"Реальные газы",q:"Температура инверсии — это температура, при которой…",options:["Газ при расширении в пустоту не меняет температуру","Газ окончательно переходит в жидкое состояние","Эффект Джоуля-Томсона достигает максимума","У реального газа меняется знак давления"],answer:0,hint:"Между «охлаждением» и «нагревом» лежит граница.",why:"При температуре инверсии эффект Джоуля-Томсона равен нулю: ниже неё газ при расширении охлаждается (+эффект), выше — нагревается (−эффект)."},
{topic:"Явления переноса",q:"Эффузия — это истечение газа через отверстие, когда…",options:["Длина свободного пробега больше размеров отверстия","Давление газа заметно выше атмосферного","Температура газа превышает критическую","Газ обладает большой внутренней вязкостью"],answer:0,hint:"Молекулы пролетают поодиночке, не сталкиваясь.",why:"Эффузия — истечение при λ > размеров отверстия (ультраразреженный газ): молекулы пролетают без столкновений друг с другом."},
{topic:"Волны",q:"Когерентные волны — это волны с…",options:["Одинаковой частотой и постоянной разностью фаз","Одинаковой амплитудой и одинаковой частотой","Одинаковой длиной волны и произвольной фазой","Любыми параметрами — это условие не требуется"],answer:0,hint:"Только такие волны дают устойчивую интерференционную картину.",why:"Когерентные — с одинаковой частотой и постоянной во времени разностью фаз: только они создают устойчивую интерференцию."},
{topic:"Колебания",q:"Пример автоколебательной системы:",options:["Часовой механизм с анкерным ходом","Маятник во внешнем поле","Камертон после удара","Качели при раскачке снаружи"],answer:0,hint:"Система сама выбирает моменты толчков.",why:"Часовой механизм: анкер с палеттами сам управляет толчками от ходового колеса — автоколебания. Камертон — свободные колебания, качели снаружи — вынужденные/параметрические."},
{topic:"Термодинамика",q:"Работа газа за круговой процесс на диаграмме (p, V) равна:",options:["Площади, ограниченной циклом","Площади под кривой процесса","Периметру контура цикла","Нулю, т.к. ΔU = 0"],answer:0,hint:"ΔU за цикл = 0, но A ≠ 0.",why:"Работа за цикл равна площади цикла (A = ∮p dV): по часовой стрелке — положительна, против — отрицательна. ΔU = 0, но A = Q₁−|Q₂|."},
{topic:"МКТ",q:"Внутренняя энергия идеального газа зависит от:",options:["Только температуры и массы газа","Давления и объёма по отдельности","Формы и размеров сосуда","Способа перехода между состояниями"],answer:0,hint:"U = (m/M)(i/2)RT — что там есть, чего нет?",why:"U = (m/M)(i/2)RT — зависит только от T (и количества вещества). От p и V по отдельности не зависит; это функция состояния."},
{topic:"Статфизика",q:"По распределению Максвелла, доля молекул с очень большими скоростями:",options:["Убывает по экспоненте ~e^(−mv²/2kT)","Растёт линейно со скоростью ~v²","Не зависит от температуры газа","Всегда равна нулю при любом v"],answer:0,hint:"Функция распределения F(v) ~ v²·e^(−mv²/2kT) — что «побеждает» при больших v?",why:"F(v) = 4πv²·(m/2πkT)^(3/2)·e^(−mv²/2kT): множитель v² растёт, но экспонента убывает быстрее → при больших v распределение спадает экспоненциально."},
{topic:"Термодинамика",q:"При изотермическом расширении идеального газа внутренняя энергия:",options:["Не изменяется","Возрастает","Убывает","Сначала растёт, потом падает"],answer:0,hint:"U зависит только от T.",why:"ΔU = 0: U идеального газа зависит только от T. По первому началу вся полученная теплота превращается в работу: Q = A."},
{topic:"Термодинамика",q:"При адиабатном расширении газ…",options:["Охлаждается","Нагревается","Не меняет температуру","Сначала нагревается"],answer:0,hint:"Работа совершается за счёт внутренней энергии.",why:"d′Q = 0 → A = −ΔU: работа идёт за счёт убыли внутренней энергии → T падает. При адиабатном сжатии — нагрев."},
{topic:"Термодинамика",q:"Почему адиабата на (p,V)-диаграмме круче изотермы?",options:["При расширении падает и V-член, и температура","Изотерма на самом деле идёт круче адиабаты","Потому что показатель γ всегда меньше единицы","Обе кривые на диаграмме параллельны друг другу"],answer:0,hint:"Из pV/T = const: при адиабате T падает.",why:"При адиабатном расширении давление падает и от роста V, и от падения T (охлаждение), поэтому p убывает быстрее, чем по изотерме: pV^γ = const, γ > 1."},
{topic:"Явления переноса",q:"В ультраразреженном газе давление больше в той части сосуда, где…",options:["Температура стенки выше","Температура ниже","Давление везде одинаково","Больше молекул"],answer:0,hint:"Равновесие — при равных потоках n⟨v⟩, а не при равных p.",why:"В вакууме равновесие — равенство потоков через отверстие: n₁⟨v₁⟩ = n₂⟨v₂⟩. Т.к. ⟨v⟩∝√T, получаем p∝√T — давление выше у горячей стороны."},
{topic:"Явления переноса",q:"При встречной изотермической эффузии H₂ и O₂ (n_кислорода = 2n_водорода) поток водорода больше потока кислорода, потому что…",options:["Средняя скорость молекул H₂ в 4 раза больше","Молекулы водорода в 4 раза тяжелее кислорода","Парциальное давление водорода вдвое выше","Концентрация молекул H₂ вдвое больше"],answer:0,hint:"⟨v⟩ ∝ 1/√m: m_кислорода/m_водорода = 16.",why:"Поток ∝ n⟨v⟩. Скорость H₂ в √(32/2) = 4 раза больше, а концентрация в 2 раза меньше → поток водорода вдвое больше, несмотря на меньшее давление."},
{topic:"Колебания",q:"Параметрический резонанс требует периодического изменения:",options:["Параметра системы в такт колебаниям","Амплитуды внешней вынуждающей силы","Частоты вынуждающей силы","Массы тела — исключительно её"],answer:0,hint:"Классический пример — качели, где меняют длину.",why:"Параметрический резонанс — раскачка через периодическое изменение параметра (длина, жёсткость): например, на качелях меняют длину маятника в такт качаниям."},
{topic:"Колебания",q:"Логарифмический декремент затухания λ равен…",options:["λ = ln[a(t)/a(t+T)] = βT","λ = ln[T₂−T₁] = β/T","λ = a(t)·e^(−βT)","λ = ω₀² − β²"],answer:0,hint:"λ = βT — логарифм отношения соседних амплитуд.",why:"λ = ln[a(t)/a(t+T)] = βT: отношение амплитуд через период e^λ. Число колебаний до убыли в e раз N_e = 1/λ."},
{topic:"Волны",q:"Узел стоячей волны — это точка, где…",options:["Амплитуда всегда равна нулю","Амплитуда всегда максимальна","Фаза колебаний скачкообразна","Скорость частиц максимальна"],answer:0,hint:"cos(2πx/λ) = 0 в этих точках.",why:"В узлах |cos(2πx/λ)| = 0 → амплитуда 0 всегда. Пучности — точки максимальной амплитуды."},
{topic:"Динамика",q:"Преобразования Галилея предполагают, что время и расстояния…",options:["Абсолютны — одинаковы во всех системах отсчёта","Зависят от скорости движения системы отсчёта","Различны в различных инерциальных системах","Относительны — зависят от выбора системы"],answer:0,hint:"Это классическая (не релятивистская) механика.",why:"В преобразованиях Галилея t = t′ и длины абсолютны; ускорение инвариантно (a = a′). Относительность величин — уже СТО."},
{topic:"МКТ",q:"Парциальное давление газа в смеси — это давление, которое…",options:["Имел бы газ, один занимая весь объём смеси","Создают совместно все газы смеси сразу","Равно полному давлению, делённому на N","Прямо зависит от массы самого сосуда"],answer:0,hint:"Сумма парциальных — закон Дальтона.",why:"Парциальное давление — давление газа, если бы он один занимал весь объём. Сумма парциальных = давление смеси (Дальтон)."},
{topic:"Статфизика",q:"Микросостояние системы задаётся:",options:["Координатами и импульсами всех частиц","Давлением, объёмом и температурой","Температурой и внутренней энергией","Энтропией и статистическим весом"],answer:0,hint:"А макросостояние — макропараметрами.",why:"Микросостояние — полным набором координат и импульсов всех частиц. Макросостояние — макропараметрами (p, V, T); его статвес Ω — число реализующих микросостояний."},
{topic:"Волны",q:"Фазовая скорость волны — это скорость перемещения…",options:["Фазы (поверхности постоянной фазы)","Частиц среды при их колебаниях","Переносимой волной энергии тела","Источника колебаний в среде"],answer:0,hint:"v = dx/dt при условии ωt − kx + α = const.",why:"Фазовая скорость — скорость перемещения волновых поверхностей (точек постоянной фазы), а не частиц — те лишь колеблются. dx/dt = ω/k = v."},
{topic:"Реальные газы",q:"Поправка b в уравнении Ван-дер-Ваальса учитывает…",options:["Собственный объём молекул","Силы притяжения","Температуру","Давление стенок"],answer:0,hint:"Свободный объём меньше V_M на эту величину.",why:"b — поправка на собственный объём молекул (b ≈ 4N_A объёмов молекулы): свободный объём V_M − b. Поправка a/V_M² — на притяжение."},
{topic:"Реальные газы",q:"Внутреннее давление p′ = a/V_M² в уравнении Ван-дер-Ваальса возникает из-за…",options:["Притяжения молекул","Отталкивания молекул","Ударов о стенки","Теплового движения"],answer:0,hint:"Молекулы у стенки «оттягиваются» назад вглубь газа.",why:"p′ = a/V_M² — внутреннее давление от сил притяжения: молекулы у стенки оттягиваются соседями вглубь, эффективное давление на стенку меньше → p = p_изм − a/V_M²... вернее p_изм = p_идеал − p′."},
{topic:"Реальные газы",q:"Аморфные твёрдые тела от кристаллов отличаются тем, что…",options:["Имеют только ближний порядок","Не имеют порядка вообще","Всегда жидкие","Имеют дальний порядок"],answer:0,hint:"Стекло — аморфное тело: перекошенная кристаллическая решётка.",why:"Аморфные тела (стекло и пр.) — с ближним порядком, но без дальнего: структура искажённая кристаллическая. Жидкие кристаллы — промежуточное состояние с ориентационным порядком."},
{topic:"МКТ",q:"Силы отталкивания между молекулами с ростом расстояния убывают…",options:["Быстрее сил притяжения (~1/r⁹⁻¹⁵ против ~1/r⁷)","Медленнее сил притяжения (~1/r⁵ против ~1/r⁷)","С той же скоростью, что и силы притяжения","По закону обратных квадратов, как 1/r²"],answer:0,hint:"Отталкивание важно лишь на очень малых r.",why:"Отталкивание ~1/r⁹⁻¹⁵ убывает быстрее притяжения ~1/r⁷: на больших r действует притяжение, на малых r < r₀ — резкое отталкивание."},
{topic:"Динамика",q:"Центр масс и центр тяжести тела совпадают…",options:["В однородном поле тяжести","Всегда при любых условиях","Никогда не совпадают","Только у шарообразных тел"],answer:0,hint:"Определения разные: одно про массу, другое про силы тяжести.",why:"Центр масс — средневзвешенная точка масс; центр тяжести — точка приложения силы тяжести. Совпадают в однородном поле (g одинаково для всех частей)."},
{topic:"Статфизика",q:"Эргодическая гипотеза утверждает, что…",options:["Все микросостояния равновероятны","Система не выходит из равновесия","Энтропия постоянна","Молекулы не сталкиваются"],answer:0,hint:"Отсюда вероятность макросостояния ∝ Ω.",why:"Эргодическая гипотеза: все микросостояния равновероятны → вероятность макросостояния пропорциональна его статистическому весу Ω."},
{topic:"Волны",q:"Интенсивность волны при удвоении амплитуды:",options:["Увеличится в 4 раза","Увеличится в 2 раза","Не изменится","Уменьшится"],answer:0,hint:"⟨j⟩ ∝ a².",why:"⟨j⟩ = ρa²ω²v/2 — пропорциональна квадрату амплитуды → при 2a интенсивность вырастет в 4 раза."},
{topic:"Колебания",q:"При сложении двух колебаний с Δα = 2πn результирующая амплитуда:",options:["A = A₁ + A₂","A = |A₁ − A₂|","A = √(A₁² + A₂²)","A = 0"],answer:0,hint:"Колебания в фазе — усиливают друг друга.",why:"При Δα = 2πn колебания в фазе: A² = A₁²+A₂²+2A₁A₂·1 = (A₁+A₂)² → A = A₁+A₂ (максимум). При Δα = (2n+1)π — минимум |A₁−A₂|."},
{topic:"Термодинамика",q:"При изобарном нагревании газа сообщённая теплота идёт на:",options:["Нагрев и работу расширения","Только нагрев внутренней энергии","Только работу внешних тел","Никуда — теплота не передаётся"],answer:0,hint:"Именно поэтому C_p > C_V.",why:"При p = const Q = ΔU + A: часть на ΔU (нагрев), часть на работу A = pΔV. Поэтому C_p = C_V + R > C_V."},
{topic:"МКТ",q:"Процесс p = const называется…",options:["Изобарным","Изотермическим","Изохорным","Адиабатным"],answer:0,hint:"«Бар» — давление.",why:"Изобарный (Гей-Люссак, V/T = const). Изохорный — V = const (Шарль), изотермический — T = const (Бойль-Мариотт), адиабатный — d′Q = 0."},
{topic:"МКТ",q:"Процесс V = const называется…",options:["Изохорным","Изобарным","Изотермическим","Политропным"],answer:0,hint:"«Хора» — объём.",why:"Изохорный процесс (закон Шарля, p/T = const). Политропный — общий случай pVⁿ = const, изохорный соответствует n → ∞."},
{topic:"Динамика",q:"Сила трения качения определяется как:",options:["F_тр.кач = η·N/R","F_тр = kN","F = −k₁v","F = kN/R²"],answer:0,hint:"Коэффициент качения η имеет размерность длины.",why:"F_тр.кач = η·N/R, где η — коэффициент трения качения (размерность длины), R — радиус катящегося тела."},
{topic:"Работа и энергия",q:"При упругом центральном ударе шара на покоящийся шар той же массы скорости…",options:["Обмениваются: первый встанет, второй полетит","Складываются: второй летит вдвое быстрее","Делятся пополам поровну между шарами","Обнуляются: оба шара останавливаются"],answer:0,hint:"Подставь m₁ = m₂ в формулы из конспекта.",why:"v₁ = (m₁−m₂)v₁₀/(m₁+m₂) = 0; v₂ = 2m₁v₁₀/(m₁+m₂) = v₁₀ — шары обмениваются скоростями."},
{topic:"Вращение",q:"Нутация гироскопа — это…",options:["Колебания оси в вертикальной плоскости","Собственное вращение вокруг своей оси","Прецессия оси в горизонтальной плоскости","Полная остановка вращения гироскопа"],answer:0,hint:"А прецессия — поворот оси в горизонтальной плоскости.",why:"Нутация — колебания оси гироскопа в вертикальной плоскости; прецессия — медленное поворачивание оси вокруг вертикали с ω′ = mgl/Iω."},
{topic:"Колебания",q:"Точки подвеса и центр качания физического маятника…",options:["Взаимны — при переносе оси период сохраняется","Всегда геометрически совпадают друг с другом","Полностью независимы и никак не связаны","Лежат на одной вертикали с центром Земли"],answer:0,hint:"Это свойство обратимости маятника.",why:"Точка подвеса и центр качания взаимны: если опустить ось в центр качания, прежняя точка подвеса станет новым центром качания, период сохранится."},
{topic:"МКТ",q:"Количество теплоты для нагрева тела выражается как:",options:["Q = cm(T₂ − T₁)","Q = c/(mΔT)","Q = mΔT/c","Q = cT²"],answer:0,hint:"c — удельная теплоёмкость, Дж/(кг·К).",why:"Q = cm(T₂−T₁) = CΔT, где c — удельная, C = cm — теплоёмкость тела."},
{topic:"Статфизика",q:"Третий закон термодинамики (Нернст) связывает энтропию и температуру:",options:["S → 0 при T → 0","S → ∞ при T → 0","S = const при любом T","T → 0 при S → ∞"],answer:0,hint:"При 0 К остаётся единственное микросостояние.",why:"При T → 0 тело переходит в единственное основное состояние: Ω = 1 → S = k·ln1 = 0."},
{topic:"Кинематика",q:"Если тангенциальное ускорение равно нулю, движение точки:",options:["Равномерное по модулю скорости","Обязательно прямолинейное","С постоянным полным ускорением","Обязательно состояние покоя"],answer:0,hint:"aτ = dv/dt = 0 → что с v?",why:"aτ = dv/dt = 0 → |v| = const — движение равномерное по модулю (но может быть криволинейным: an ≠ 0)."},
{topic:"Динамика",q:"Система отсчёта называется ц-системой, если в ней…",options:["Центр масс системы покоится","Все тела системы покоятся","Не действуют никакие силы","Ускорение тел равно нулю"],answer:0,hint:"«ц» — от «центра масс».",why:"Ц-система — система отсчёта, где центр масс покоится (p = 0); она инерциальна."},
{topic:"Волны",q:"Сферическая волна отличается от плоской тем, что…",options:["Амплитуда убывает как a/r","Амплитуда постоянна","Не переносит энергию","Имеет плоский фронт"],answer:0,hint:"Энергия распределяется по растущей сфере — по закону интенсивности ~1/r².",why:"В сферической волне ξ = (a/r)cos(ωt − kr + α): амплитуда убывает как 1/r (интенсивность ~ 1/r² — энергия делится на площадь сферы)."},
{topic:"Термодинамика",q:"Цикл Отто (карбюраторный ДВС) состоит из:",options:["Двух изохор и двух адиабат","Двух изотерм и двух адиабат","Двух изобар и двух изохор","Четырёх адиабат"],answer:0,hint:"Подвод и отвод тепла при V = const.",why:"Цикл Отто: две изохоры (подвод и отвод тепла при постоянном объёме) + две адиабаты. Дизель: адиабаты + изобара + изохора."},
{topic:"Явления переноса",q:"В ультраразреженном газе теплопроводность отличается от обычной тем, что…",options:["Пропорциональна давлению (плотности газа)","От давления вообще не зависит","Всегда равна нулю при вакууме","Растёт квадратично с давлением"],answer:0,hint:"λ ~ ρ⟨v⟩λ_пр; но в вакууме λ_пр ≈ размеры сосуда, а ρ — нет.",why:"В вакууме λ_пр фиксирован размерами сосуда, поэтому λ_тепл = (1/6)ρ⟨v⟩c_V ∝ ρ ∝ p — теплопередача падает с понижением давления (принцип термоса)."},
{topic:"Реальные газы",q:"Упругость насыщенного пара на изотермах Эндрюса — это…",options:["Давление начала горизонтального участка (плато)","Давление изотермы в критической точке газа","Давление, равное нормальному атмосферному","Давление вещества в его тройной точке"],answer:0,hint:"Плато — сосуществование двух фаз при постоянном давлении.",why:"Упругость (давление) насыщенного пара — давление, при котором начинается сжижение, т.е. давление горизонтального участка изотермы; убывает с температурой."},
{topic:"Колебания",q:"Векторная диаграмма представляет колебание как…",options:["Проекцию вращающегося вектора на ось","График зависимости x от t","Траекторию движения частицы","Волновую поверхность в среде"],answer:0,hint:"Вектор длины a вращается с угловой скоростью ω.",why:"Колебание изображается вектором a, вращающимся с ω: его проекция на ось — гармоническое колебание. Удобно для сложения: векторы складываются."},
{topic:"МКТ",q:"Статистическая физика в отличие от термодинамики…",options:["Исходит из свойств частиц и их взаимодействий","Вообще не рассматривает молекулы","Изучает исключительно равновесие","Не использует понятие вероятности"],answer:0,hint:"А термодинамика — феноменологическая, на «началах».",why:"Статфизика исходит из микроскопического строения (свойств частиц, взаимодействий); термодинамика — феноменологична, опирается на начала. Физическая кинетика — про неравновесные процессы."},
{topic:"Динамика",q:"Закон сохранения импульса следует из…",options:["Однородности пространства","Однородности времени","Изотропии пространства","Принципа относительности"],answer:0,hint:"Три симметрии — три закона: энергия/импульс/момент.",why:"Импульс — из однородности пространства; энергия — из однородности времени; момент импульса — из изотропии пространства."}
];

